const records = $input.all();
const period = $('Webhook: Report Request').item.json.body.period;
let totalTaxable = 0, totalCGST = 0, totalSGST = 0, totalIGST = 0;
const byRate = {};
records.forEach(r => {
  const d = r.json;
  totalCGST += parseFloat(d.total_cgst || 0);
  totalSGST += parseFloat(d.total_sgst || 0);
  totalIGST += parseFloat(d.total_igst || 0);
});
totalTaxable = (totalCGST + totalSGST + totalIGST) * 2;
const fmt = n => '₹' + parseFloat(n).toFixed(2);
const html = `<h2>GST Summary — ${period}</h2><table border='1' cellpadding='8' style='border-collapse:collapse'><tr><th>Total Taxable</th><td>${fmt(totalTaxable)}</td></tr><tr><th>Total CGST</th><td>${fmt(totalCGST)}</td></tr><tr><th>Total SGST</th><td>${fmt(totalSGST)}</td></tr><tr><th>Total IGST</th><td>${fmt(totalIGST)}</td></tr><tr><th>Total Tax</th><td>${fmt(totalCGST+totalSGST+totalIGST)}</td></tr></table><p><em>Auto-generated by BillFlow. Verify with accountant before filing.</em></p>`;
return [{ json: { html_report: html, period, totalCGST, totalSGST, totalIGST, totalTaxable, record_count: records.length } }];

const bills = $input.all();
const period = $('Webhook: Report Request').item.json.body.period;
let total = 0;
bills.forEach(b => { total += parseFloat(b.json.grand_total || 0); });
const html = `<h2>Revenue Report — ${period}</h2><p>Total Revenue: ₹${total.toFixed(2)}</p><p>Bills Paid: ${bills.length}</p><p><em>Auto-generated by BillFlow</em></p>`;
return [{ json: { html_report: html, period, total_revenue: total, bill_count: bills.length } }];

const bills = $input.all();
let total = 0;
const rows = bills.map(b => { total += parseFloat(b.json.grand_total || 0); return `<tr><td>${b.json.bill_number}</td><td>₹${b.json.grand_total}</td><td>${b.json.due_date}</td></tr>`; }).join('');
const html = `<h2>Overdue Bills Report</h2><table border='1' cellpadding='8' style='border-collapse:collapse'><tr><th>Invoice</th><th>Amount</th><th>Due Date</th></tr>${rows}</table><p>Total Outstanding: ₹${total.toFixed(2)} across ${bills.length} bills.</p>`;
return [{ json: { html_report: html, total_overdue: total, count: bills.length } }];

const today = new Date().toLocaleDateString('en-IN', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
// Note: In real execution, these come from previous nodes
const overdueBills = [];
const dueTodayBills = [];
const revenueBills = [];

let overdueTotal = overdueBills.reduce((s, b) => s + parseFloat(b.json?.grand_total || 0), 0);
let monthRevenue = revenueBills.reduce((s, b) => s + parseFloat(b.json?.grand_total || 0), 0);

const dueTodayRows = dueTodayBills.length > 0
  ? dueTodayBills.map(b => `<tr><td>${b.json?.bill_number}</td><td>₹${b.json?.grand_total}</td></tr>`).join('')
  : '<tr><td colspan="2">No bills due today 🎉</td></tr>';

const html = `<h2>📊 BillFlow Daily Summary</h2><h3>${today}</h3><h3>📋 Bills Due Today (${dueTodayBills.length})</h3><table border='1' cellpadding='8' style='border-collapse:collapse'><tr><th>Invoice</th><th>Amount</th></tr>${dueTodayRows}</table><h3>⚠️ Overdue Bills</h3><p>${overdueBills.length} bills overdue — Total: ₹${overdueTotal.toFixed(2)}</p><h3>💰 This Month's Revenue</h3><p>Collected: ₹${monthRevenue.toFixed(2)} from ${revenueBills.length} paid bills</p><p style='color:#888;font-size:12px'>— BillFlow Automation</p>`;

return [{ json: { html_summary: html, today, overdue_count: overdueBills.length, overdueTotal, monthRevenue, due_today_count: dueTodayBills.length } }];

const d = new Date();
d.setDate(d.getDate() + 7);
return [{ json: { due_date_7: d.toISOString().split('T')[0] } }];

const d = new Date();
d.setDate(d.getDate() + 3);
return [{ json: { due_date_3: d.toISOString().split('T')[0] } }];

const d = new Date();
d.setDate(d.getDate() + 1);
return [{ json: { due_date_1: d.toISOString().split('T')[0] } }];

// Alert owner about all bills due tomorrow
const bills = $input.all();
const list = bills.map(b => `- ${b.json.bill_number}: ₹${b.json.grand_total}`).join('\n');
return [{ json: { owner_alert_text: `Bills due TOMORROW (${new Date().toLocaleDateString('en-IN')}):\n${list}` } }];

const d = new Date();
d.setDate(d.getDate() - 1);
return [{ json: { yesterday: d.toISOString().split('T')[0] } }];

const d = new Date();
d.setDate(d.getDate() - 7);
return [{ json: { overdue_since: d.toISOString().split('T')[0] } }];

const d = new Date();
d.setDate(d.getDate() - 30);
return [{ json: { overdue_since_30: d.toISOString().split('T')[0], escalation_date: new Date().toISOString().split('T')[0] } }];

const bills = $input.all();
const today = new Date();
const fmt = n => '₹' + parseFloat(n).toFixed(2);

let buckets = { '1_7': [], '8_30': [], '31_60': [], '60plus': [] };

bills.forEach(b => {
  const dueDate = new Date(b.json.due_date);
  const days = Math.floor((today - dueDate) / 86400000);
  if (days <= 7) buckets['1_7'].push(b.json);
  else if (days <= 30) buckets['8_30'].push(b.json);
  else if (days <= 60) buckets['31_60'].push(b.json);
  else buckets['60plus'].push(b.json);
});

const sum = arr => arr.reduce((s, b) => s + parseFloat(b.grand_total || 0), 0);

const makeRows = arr => arr.map(b => `<tr><td>${b.bill_number}</td><td>${b.customers?.name || '-'}</td><td>${fmt(b.grand_total)}</td><td>${b.due_date}</td></tr>`).join('');

const html = `<h2>📊 Weekly Overdue Ageing Report</h2><h3>${today.toLocaleDateString('en-IN', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</h3><table border='1' cellpadding='8' style='border-collapse:collapse'><tr><th>Bucket</th><th>Count</th><th>Total</th></tr><tr><td>1–7 Days</td><td>${buckets['1_7'].length}</td><td>${fmt(sum(buckets['1_7']))}</td></tr><tr><td>8–30 Days</td><td>${buckets['8_30'].length}</td><td>${fmt(sum(buckets['8_30']))}</td></tr><tr><td>31–60 Days</td><td>${buckets['31_60'].length}</td><td>${fmt(sum(buckets['31_60']))}</td></tr><tr><td>60+ Days</td><td>${buckets['60plus'].length}</td><td>${fmt(sum(buckets['60plus']))}</td></tr><tr style='font-weight:bold'><td>TOTAL</td><td>${bills.length}</td><td>${fmt(sum(bills.map(b=>b.json)))}</td></tr></table><h3>All Overdue Bills</h3><table border='1' cellpadding='8' style='border-collapse:collapse'><tr><th>Invoice</th><th>Customer</th><th>Amount</th><th>Due Date</th></tr>${makeRows(bills.map(b=>b.json))}</table>`;

return [{ json: { html_report: html, total_count: bills.length, total_amount: sum(bills.map(b=>b.json)) } }];

const now = new Date();
const prevMonth = new Date(now.getFullYear(), now.getMonth() - 1, 1);
const lastDay = new Date(now.getFullYear(), now.getMonth(), 0);
const from = prevMonth.toISOString().split('T')[0];
const to   = lastDay.toISOString().split('T')[0];
const monthName = prevMonth.toLocaleString('en-IN', { month: 'long' });
const year = prevMonth.getFullYear();
return [{ json: { from, to, monthName, year } }];

const records = $input.all();
const { monthName, year } = $('Calculate: Previous Month').item.json;
let totalCGST = 0, totalSGST = 0, totalIGST = 0;
records.forEach(r => {
  totalCGST += parseFloat(r.json.total_cgst || 0);
  totalSGST += parseFloat(r.json.total_sgst || 0);
  totalIGST += parseFloat(r.json.total_igst || 0);
});
const totalTax = totalCGST + totalSGST + totalIGST;
const totalTaxable = totalTax * 2;
const fmt = n => '₹' + n.toFixed(2);

const html = `<h2>GST Collection Summary — ${monthName} ${year}</h2><p><strong>Business:</strong> ${process.env.EMAIL_FROM_NAME || 'Your Business'}</p><table border='1' cellpadding='10' style='border-collapse:collapse;width:100%'><tr style='background:#f0f0f0'><th>Tax Type</th><th>Amount</th></tr><tr><td>Total Taxable Value</td><td>${fmt(totalTaxable)}</td></tr><tr><td>CGST Collected</td><td>${fmt(totalCGST)}</td></tr><tr><td>SGST Collected</td><td>${fmt(totalSGST)}</td></tr><tr><td>IGST Collected</td><td>${fmt(totalIGST)}</td></tr><tr style='font-weight:bold;background:#fffde7'><td>Total Tax Collected</td><td>${fmt(totalTax)}</td></tr></table><p><em>⚠️ This is an auto-generated summary. Please verify with your accountant before filing GSTR returns.</em></p><p>— BillFlow Automation</p>`;

return [{ json: { html_report: html, monthName, year, totalCGST, totalSGST, totalIGST, totalTax, totalTaxable, record_count: records.length } }];

const now = new Date();
const month = now.getMonth() + 1;
const year = now.getFullYear();
const quarters = { 3: 'Q4 (Jan–Mar)', 6: 'Q1 (Apr–Jun)', 9: 'Q2 (Jul–Sep)', 12: 'Q3 (Oct–Dec)' };
const quarterEnds = { 3: `31 March ${year}`, 6: `30 June ${year}`, 9: `30 September ${year}`, 12: `31 December ${year}` };
const gstr1Dues   = { 3: `11 April ${year}`, 6: `11 July ${year}`, 9: `11 October ${year}`, 12: `11 January ${year + 1}` };
const gstr3bDues  = { 3: `20 April ${year}`, 6: `20 July ${year}`, 9: `20 October ${year}`, 12: `20 January ${year + 1}` };
return [{ json: { quarter: quarters[month], quarter_end: quarterEnds[month], gstr1_due: gstr1Dues[month], gstr3b_due: gstr3bDues[month] } }];

const today = new Date();
const lastMonday = new Date(today);
lastMonday.setDate(today.getDate() - 7);
const lastSunday = new Date(today);
lastSunday.setDate(today.getDate() - 1);
const thisMonthStart = new Date(today.getFullYear(), today.getMonth(), 1);
return [{
  json: {
    week_from:    lastMonday.toISOString().split('T')[0],
    week_to:      lastSunday.toISOString().split('T')[0],
    month_start:  thisMonthStart.toISOString().split('T')[0],
    today:        today.toISOString().split('T')[0]
  }
}];

const weekBills = $('Fetch: Last Week Paid Bills').all();
const monthBills = $('Fetch: Month Revenue So Far').all();

const { week_from, week_to } = $('Calculate: Week Dates').item.json;

let weekRevenue = 0;
const custMap = {};
weekBills.forEach(b => {
  const amt = parseFloat(b.json.grand_total || 0);
  weekRevenue += amt;
  const name = b.json.customers?.name || 'Unknown';
  custMap[name] = (custMap[name] || 0) + amt;
});

const topCustomer = Object.keys(custMap).reduce((a, b) => custMap[a] > custMap[b] ? a : b, '');
const monthRevenue = monthBills.reduce((s, b) => s + parseFloat(b.json.grand_total || 0), 0);

const fmt = n => '₹' + n.toFixed(2);
const html = `<h2>📈 Weekly Revenue Report</h2><h3>Last Week: ${week_from} to ${week_to}</h3><table border='1' cellpadding='10' style='border-collapse:collapse;width:100%'><tr><th>Metric</th><th>Value</th></tr><tr><td>Revenue Collected</td><td>${fmt(weekRevenue)}</td></tr><tr><td>Bills Paid</td><td>${weekBills.length}</td></tr><tr><td>Best Customer</td><td>${topCustomer} (${fmt(custMap[topCustomer] || 0)})</td></tr></table><h3>This Month So Far</h3><table border='1' cellpadding='10' style='border-collapse:collapse;width:100%'><tr><td>Month Revenue</td><td>${fmt(monthRevenue)}</td></tr><tr><td>Month Bills Paid</td><td>${monthBills.length}</td></tr></table><p>— BillFlow Automation</p>`;

return [{ json: { html_report: html, weekRevenue, monthRevenue, weekBillCount: weekBills.length, topCustomer } }];
